  var DEF = {"id":"p4","sceneId":"p4","title":"射孔效果智能评估","methods":["ts","opt"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":null,"lede":"射孔效果（完善度、表皮系数）只能通过试井或生产数据间接反演，评估结果直接影响是否补孔或重复射孔。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>试井资料有限，多数井只有生产数据；人工判断低效射孔段缺乏定量依据。<\/p>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>从生产数据反演射孔效率，识别低效段并给出补孔建议。<\/p>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p>· 生产数据：产量、压力、含水（单井 1000—10000 点）<\/p><p>· 射孔记录：层段、孔密、相位（作为输入）<\/p><p>· 试井解释：表皮系数（少量真值）<\/p>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>难度：中。反演问题多解，需与地质认识结合，避免\"数学最优、地质不合理\"。<\/p><p>参考方向：反演、生产数据分析、不确定性量化。<\/p><p>交叉环节：采油、完井。<\/p>"}]},"workflow":null}};
